    public static string GetAppSettings()
    {
        return """
        {
            "featureFlags": {
                "darkMode": true,
                "betaFeatures": false
            },
            "limits": {
                "maxUploadSizeMb": 50,
                "requestsPerMinute": 100
            },
            "version": "1.2.0"
        }
        """;
    }

    [McpServerResource(UriTemplate = "config://app/env/{environment}", Name = "env_config",
        MimeType = "application/json"), Description("Returns environment-specific configuration.")]
    public static string GetEnvConfig(string environment)
    {
        return environment.ToLowerInvariant() switch
        {
            "production" => """{ "logLevel": "Warning", "cacheMinutes": 60, "debugMode": false }""",
            "staging"    => """{ "logLevel": "Information", "cacheMinutes": 5, "debugMode": false }""",
            _            => """{ "logLevel": "Debug", "cacheMinutes": 0, "debugMode": true }"""
        };
    }
}

